class RotationTimeline:
    """按审计 seq 严格校验后的连续份额轮换时间线（纯内存，不触盘）。

    - ``entries`` 按 prepared 事件 seq 升序，每个轮换恰一条，记录其
      prepared_seq、activated_seq（未激活为 None）、有序 share_ids、
      public_key、previous_public_key（仅激活后有）；
    - ``committed`` 为已激活条目，按激活事件 seq 升序，其
      previous_public_key 构成连续公钥链（首条之前为创世公钥
      ``genesis_public_key``）；
    - ``residue_ids`` 为有轮换记录却没有 prepared 事件的 rotation_id
      （准备未提交的崩溃残留，恢复时连记录带暂存安全删除）。

    任何事件缺失、重复、乱序、跨轮次不相容、事件与记录不一致都抛
    RecoveryError：调用方必须 fail-closed，绝不猜写密钥或归一现场。
    """

    def __init__(
        self,
        entries: list[dict],
        residue_ids: set[str],
    ) -> None:
        self.entries = entries
        self.residue_ids = residue_ids
        self.committed = [e for e in entries if e["activated_seq"] is not None]
        self.genesis_public_key: Optional[str] = (
            self.committed[0]["previous_public_key"]
            if self.committed
            else None
        )

    @property
    def latest(self) -> Optional[dict]:
        """最近一次已提交激活的条目；从未激活过时为 None。"""
        return self.committed[-1] if self.committed else None

    def live_share_ids(self) -> tuple[str, str]:
        """时间线当前在用两份份额（无激活时为创世份额）。"""
        if self.committed:
            ids = self.committed[-1]["share_ids"]
            return ids[0], ids[1]
        return ("share-1", "share-2")

    def live_public_key(self, fallback: Optional[str] = None) -> Optional[str]:
        """当前在用钱包公钥：最近激活的公钥；无激活时用调用方给出的
        （钱包元数据中的）创世公钥。"""
        if self.committed:
            return self.committed[-1]["public_key"]
        return fallback

    def retired_share_ids(self) -> set[str]:
        """所有曾被后续轮换淘汰、当前不应再留在在用份额目录中的份额 id。"""
        retired: set[str] = set()
        if self.committed:
            retired.update(("share-1", "share-2"))
            for entry in self.committed[:-1]:
                retired.update(entry["share_ids"])
        # 未提交激活的轮换份额也绝不能留在在用目录（回滚后只应在暂存中）
        for entry in self.entries:
            if entry["activated_seq"] is None:
                retired.update(entry["share_ids"])
        latest = self.live
        if latest is not None:
            retired.difference_update(latest["share_ids"])
        else:
            retired.difference_update(("share-1", "share-2"))
        return retired


def _rotation_event_detail_ok(details: object, *, with_previous: bool) -> bool:
    if not isinstance(details, dict):
        return False
    rotation_id = details.get("rotation_id")
    if not _valid_safe_id(rotation_id):
        return False
    share_ids = details.get("share_ids")
    if (
        not isinstance(share_ids, list)
        or len(share_ids) != 2
        or len(set(share_ids)) != 2
        or any(not isinstance(sid, str) or not _SAFE_SHARE_ID.match(sid)
               for sid in share_ids)
    ):
        return False
    public_key = details.get("public_key")
    if not isinstance(public_key, str):
        return False
    try:
        if len(bytes.fromhex(public_key)) != 64:
            return False
    except ValueError:
        return False
    if with_previous:
        previous = details.get("previous_public_key")
        if not isinstance(previous, str):
            return False
        try:
            if len(bytes.fromhex(previous)) != 64:
                return False
        except ValueError:
            return False
    return True


def build_rotation_timeline(
    events: list[dict], records: dict[str, dict]
) -> RotationTimeline:
    """以仅追加审计中的轮换事件序列为权威，构建连续公钥/份额时间线。

    ``events`` 为 prepared/activated 轮换事件（按 seq 升序）；``records``
    为轮换记录文件内容（rotation_id -> record）。严格拒绝：

    - seq 非正整数、布尔、重复或乱序；
    - 事件 details 形状非法（rotation_id/share_ids/public_key/
      previous_public_key 缺失或非法）；
    - activated 没有对应 prepared（缺失）、同一轮换 prepared/activated
      重复、上一轮未激活就准备/激活下一轮（乱序）；
    - 同一轮换 prepared 与 activated 的 share_ids/public_key 不一致；
    - 相邻激活断链：本轮 previous_public_key 不等于上一轮 public_key，
      或新旧公钥相同、新旧份额集合相交（跨轮次不相容）；
    - 事件与记录不一致：记录缺失、state 与事件矛盾、share_ids/public_key/
      previous_public_key 与事件不符；
    - 各轮份额 id 与创世份额或历史轮次冲突（同一 id 解析出两把公钥）。
    """
    entries_by_id: dict[str, dict] = {}
    order: list[str] = []
    seen_share_sets: set[tuple[str, str]] = {("share-1", "share-2")}
    open_id: Optional[str] = None
    previous_public_key: Optional[str] = None
    last_seq = 0

    for event in events:
        seq = event.get("seq")
        if not isinstance(seq, int) or isinstance(seq, bool) or seq < 1:
            raise RecoveryError("rotation event has an illegal seq")
        if seq <= last_seq:
            raise RecoveryError("rotation events are missing or out of order")
        last_seq = seq
        event_type = event.get("type")
        with_previous = event_type == "share_rotation_activated"
        details = event.get("details")
        if not _rotation_event_detail_ok(details, with_previous=with_previous):
            raise RecoveryError("rotation event has malformed details")
        rotation_id = details["rotation_id"]
        share_ids = (details["share_ids"][0], details["share_ids"][1])
        public_key = details["public_key"]

        if event_type == "share_rotation_prepared":
            if rotation_id in entries_by_id:
                raise RecoveryError(
                    f"rotation {rotation_id!r} prepared event is duplicated"
                )
            if open_id is not None:
                raise RecoveryError(
                    f"rotation {rotation_id!r} prepared while rotation "
                    f"{open_id!r} is not activated yet"
                )
            if share_ids in seen_share_sets:
                raise RecoveryError(
                    f"rotation {rotation_id!r} reuses share ids from an "
                    "earlier share set"
                )
            seen_share_sets.add(share_ids)
            entries_by_id[rotation_id] = {
                "rotation_id": rotation_id,
                "prepared_seq": seq,
                "activated_seq": None,
                "share_ids": share_ids,
                "public_key": public_key,
                "previous_public_key": None,
            }
            order.append(rotation_id)
            open_id = rotation_id
            continue

        # activated
        entry = entries_by_id.get(rotation_id)
        if entry is None:
            raise RecoveryError(
                f"rotation {rotation_id!r} activated without a prepared event"
            )
        if open_id != rotation_id or entry["activated_seq"] is not None:
            raise RecoveryError(
                f"rotation {rotation_id!r} activated event is duplicated or "
                "out of order"
            )
        if (
            share_ids != entry["share_ids"]
            or public_key != entry["public_key"]
        ):
            raise RecoveryError(
                f"rotation {rotation_id!r} activated event does not match its "
                "prepared event"
            )
        event_previous = details["previous_public_key"]
        if public_key == event_previous:
            raise RecoveryError(
                f"rotation {rotation_id!r} activates the same public key"
            )
        if previous_public_key is None:
            # 首条激活：确立创世公钥；后续每轮都必须与上一轮链接
