# Check no unused imports introduced
import ast, sys
for path in ("threshold_wallet/store.py", "threshold_wallet/service.py", "threshold_wallet/audit.py"):
    src = open(path).read()
    tree = ast.parse(src)
    imported = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom):
            for n in node.names:
                imported.add(n.asname or n.name)
        elif isinstance(node, ast.Import):
            for n in node.names:
                imported.add((n.asname or n.name).split(".")[0])
    used = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)}
    used |= {n.attr for n in ast.walk(tree) if isinstance(n, ast.Attribute)}
    missing = [i for i in imported if i not in used and i not in ("annotations",)]
    if missing:
        print(path, "possibly unused:", missing)
print("done")
EOF

